<?php $item = $item ?? []; $prodi = $prodi ?? []; ?>
<div class="row justify-content-center"><div class="col-lg-7"><a href="<?= BASE_URL ?>/matakuliah" class="text-decoration-none">&larr; Kembali</a><h1 class="h2 mt-3 mb-4"><?= $item !== [] ? 'Edit' : 'Tambah' ?> Mata Kuliah</h1><?php if (isset($error)): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form action="<?= BASE_URL ?>/matakuliah<?= $item !== [] ? '/' . $item['id'] : '' ?>" method="post" class="card border-0 shadow-sm"><div class="card-body p-4"><label class="form-label" for="kode">Kode</label><input class="form-control mb-3" id="kode" name="kode" value="<?= htmlspecialchars($item['kode'] ?? '', ENT_QUOTES, 'UTF-8') ?>" required><label class="form-label" for="nama">Nama</label><input class="form-control mb-3" id="nama" name="nama" value="<?= htmlspecialchars($item['nama'] ?? '', ENT_QUOTES, 'UTF-8') ?>" required><label class="form-label" for="sks">SKS</label><input type="number" min="1" max="6" class="form-control mb-3" id="sks" name="sks" value="<?= htmlspecialchars($item['sks'] ?? '', ENT_QUOTES, 'UTF-8') ?>" required><label class="form-label" for="prodi_id">Program Studi</label><select class="form-select mb-4" id="prodi_id" name="prodi_id" required><?php foreach ($prodi as $option): ?><option value="<?= $option['id'] ?>" <?= $item !== [] && (int) $item['prodi_id'] === (int) $option['id'] ? 'selected' : '' ?>><?= htmlspecialchars($option['kode'] . ' - ' . $option['nama'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><div class="text-end"><a href="<?= BASE_URL ?>/matakuliah" class="btn btn-light border">Batal</a> <button class="btn btn-primary">Simpan</button></div></div></form></div></div>